head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.vAcptNo = "";
scwin.vIsurCd = "";
scwin.vOpenTyp = "";
// 세션정보를 얻기위한 함수사용
scwin.getPar, scwin.setPar;
scwin.TR_JOB;
scwin.vSYMBL_INPUT_CD;
scwin.vSecuGrpId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // var parentWin = fn_GetProvider();
        const parentWin = $c.frame.path("../");
        // alert('[parentWin]'+parentWin);
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        scwin.vAcptNo = parentWin.scwin.vAcptNo;
        scwin.vIsurCd = parentWin.scwin.vIsurCd;
        scwin.vOpenTyp = parentWin.scwin.vOpenTyp;
        scwin.vSecuGrpId = parentWin.fr_SecuGrpId;
        txb_ISU_CD.setValue(parentWin.txb_ISU_CD.getValue());
        txb_ISU_NM.setValue(parentWin.txb_ISU_NM.getValue());
        $c.libRoundPanel.PanelToGroupBox(panel_Item);
        scwin.vSYMBL_INPUT_CD = js_market;
        scwin.setComponentSymbl();

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성s
        // buttonSet.setDrftInfo( btn_Drft, fn_drft );            // 기안

        // 2010.12.30 ETF 종목명 변경
        if (scwin.vOpenTyp === "R") {
            await scwin.recvReadSync();
            if (dts_Isu.getCellData(1, "AFCHG_ISU_KOR_NM") === "-") {
                dts_Isu.setCellData(1, "AFCHG_ISU_KOR_NM", "");
            }
            if (dts_Isu.getCellData(1, "AFCHG_ISU_KOR_ABBRV") === "-") {
                dts_Isu.setCellData(1, "AFCHG_ISU_KOR_ABBRV", "");
            }
            if (dts_Isu.getCellData(1, "AFCHG_ISU_ENG_NM") === "-") {
                dts_Isu.setCellData(1, "AFCHG_ISU_ENG_NM", "");
            }
            if (dts_Isu.getCellData(1, "AFCHG_ISU_ENG_ABBRV") === "-") {
                dts_Isu.setCellData(1, "AFCHG_ISU_ENG_ABBRV", "");
            }
            if (dts_Isu.getCellData(1, "AFCHG_ISU_ENG_SYMBL") === "-") {
                dts_Isu.setCellData(1, "AFCHG_ISU_ENG_SYMBL", "");
            }
        } else if (scwin.vOpenTyp === "H") {
            await scwin.readSync();
        } else if (scwin.vOpenTyp === "N") {
            await scwin.bfReadSync();
        }
        if (scwin.vSecuGrpId === SECUGRP_ID_EF) {
            txb_memo.setDisabled(false);
            txb_memo.setValue("* '변경후' 종목명에 값이 없을 경우 '변경전' 종목명 값으로 저장됩니다.");
        } else {
            txb_memo.setDisabled(true);
        }
        buttonSet.setButtonSecugrpDepCd(dts_ByCorpDepCd, scwin.vSecuGrpId, scwin.vIsurCd, js_dep_cd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05317.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_MKTACT_ENFORCE_DD_onclick
 * @description img_MKTACT_ENFORCE_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_MKTACT_ENFORCE_DD_onclick = function() {
    try {
        popUpCalendar2(edt_MKTACT_ENFORCE_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05317.img_MKTACT_ENFORCE_DD_onclick" });
    }
};

/**
 * @method
 * @name img_ISU_ENG_SYMBL_onclick
 * @description 「중복체크」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_ISU_ENG_SYMBL_onclick = async function() {
    try {
        if (edt_AFCHG_ISU_ENG_SYMBL.getValue() === "") {
            await $c.win.alert("[영문종목심볼]을 입력하세요.");
            edt_AFCHG_ISU_ENG_SYMBL.focus();
            return false;
        } else {
            $c.lc.fn_chkIsuSymblDoubleInput(edt_AFCHG_ISU_ENG_SYMBL.getValue(), txb_ISU_CD.getValue(), dts_Symbl);
            if (!$c.ut.isEmpty(MSG_SYMBL_DOUBLE_INPUT)) {
                await $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05317.img_ISU_ENG_SYMBL_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05317.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_RecvIsuDel_onclick
 * @description 「신청종목삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_RecvIsuDel_onclick = async function() {
    try {
        await scwin.recvtIsuDel();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05317.btn_RecvIsuDel_onclick" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadError
 * @description dts_Isu 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Isu);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05317.dts_Isu_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vOpenTyp === "N" || (scwin.vOpenTyp === "R")) {
            buttonSet.setInsertStatus();
        } else {
            $c.stf.setButtonSetWithDate(edt_MKTACT_ENFORCE_DD, false);
            $c.stf.setButtonSetWithDate2(dts_Isu.getCellData(1, "DISCLS_YN"));
        }
        if (scwin.vOpenTyp === "R") {
            btn_RecvIsuDel.setBackgroundImage("../img/btn_RcvdocDel.gif");
            btn_RecvIsuDel.setDisabled(false);
        } else {
            btn_RecvIsuDel.setBackgroundImage("../img/btn_RcvdocDel_d.gif");
            btn_RecvIsuDel.setDisabled(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05317.dts_Isu_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05317.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        scwin.parentRefresh();
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            scwin.vOpenTyp = "H";
            await scwin.readSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05317.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name bfReadSync
 * @description bf Read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.bfReadSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05317.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuNmChgList&DIV_IDX=" + DIV_IDX_ISU_NM_BF_INFO + "&ISU_CD=" + txb_ISU_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/Listing.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name recvReadSync
 * @description recv Read Sync 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.recvReadSync = async function(row) {
    url += "?SCREN_ID=" + "ULDSTF05317.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuNmChgList&DIV_IDX=" + DIV_IDX_ISU_NM_RECV_READ + "&ACPT_NO=" + scwin.vAcptNo;
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/Listing.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function(row) {
    url += "?SCREN_ID=" + "ULDSTF05317.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuNmChgList&DIV_IDX=" + DIV_IDX_ISU_NM_HIST_READ + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/Listing.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    if (scwin.TR_JOB === 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB === 'D') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : trsIdx,
    //     ACPT_NO : scwin.vAcptNo,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     COUNT : "1",
    //     LIST_BZ_TP_CD : scwin.VListBzTpCd + ",DIV_IDX[0]=" + DIV_IDX_ISUNM_CHG
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/Listing.do",
        ref : "dts_Isu",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    scwin.removeEnter();
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if (edt_MKTACT_ENFORCE_DD.getValue() === "") {
        await $c.win.alert("[변경일]을 입력하세요.");
        edt_MKTACT_ENFORCE_DD.focus();
        return false;
    }
    if (vCurDate >= edt_MKTACT_ENFORCE_DD.getValue()) {
        await $c.win.alert("[변경일]을 현재일이후로 입력하세요.");
        edt_MKTACT_ENFORCE_DD.focus();
        return false;
    }

    // (3264)2010.12.27 ETF 종목명 변경
    if (scwin.vSecuGrpId === SECUGRP_ID_EF) {
        if (txb_AFCHG_ISU_KOR_NM.getValue() !== "") {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_KOR_NM, 80, "한글종목명")) return false;
        }
        if (txb_AFCHG_ISU_KOR_ABBRV.getValue() !== "") {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_KOR_ABBRV, 40, "한글종목약명")) return false;
        }
        if (edt_AFCHG_ISU_ENG_NM.getValue() !== "") {
            if (!$c.stf.checkMaxLength(edt_AFCHG_ISU_ENG_NM, 80, "영문종목명")) return false;
        }
        if (edt_AFCHG_ISU_ENG_ABBRV.getValue() !== "") {
            if (!$c.stf.checkMaxLength(edt_AFCHG_ISU_ENG_ABBRV, 40, "영문종목약명")) return false;
        }
        if (scwin.vSYMBL_INPUT_CD === '1') {
            if (scwin.vSecuGrpId === SECUGRP_ID_EF || scwin.vSecuGrpId === SECUGRP_ID_FE) {
                if (edt_AFCHG_ISU_ENG_SYMBL.getValue() !== "") {
                    if (!$c.lc.fn_chkIsuSymblDoubleInput(edt_AFCHG_ISU_ENG_SYMBL.getValue(), txb_ISU_CD.getValue(), dts_Symbl)) {
                        await $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                        return false;
                    }
                }
            }
        }
    } else {
        if (txb_AFCHG_ISU_KOR_NM.getValue() === "") {
            await $c.win.alert("[한글종목명]을 입력하세요.");
            txb_AFCHG_ISU_KOR_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_KOR_NM, 80, "한글종목명")) return false;
        if (txb_AFCHG_ISU_KOR_ABBRV.getValue() === "") {
            await $c.win.alert("[한글종목약명]을 입력하세요.");
            txb_AFCHG_ISU_KOR_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_KOR_ABBRV, 40, "한글종목약명")) return false;
        if (edt_AFCHG_ISU_ENG_NM.getValue() === "") {
            await $c.win.alert("[영문종목명]을 입력하세요.");
            edt_AFCHG_ISU_ENG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(edt_AFCHG_ISU_ENG_NM, 80, "영문종목명")) return false;
        if (edt_AFCHG_ISU_ENG_ABBRV.getValue() === "") {
            await $c.win.alert("[영문종목약명]을 입력하세요.");
            edt_AFCHG_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(edt_AFCHG_ISU_ENG_ABBRV, 40, "영문종목약명")) return false;
        if (scwin.vSYMBL_INPUT_CD === '1') {
            if (scwin.vSecuGrpId === SECUGRP_ID_EF || scwin.vSecuGrpId === SECUGRP_ID_FE) {
                if (edt_AFCHG_ISU_ENG_SYMBL.getValue() === "") {
                    await $c.win.alert("[영문종목심볼]을 입력하세요.");
                    edt_AFCHG_ISU_ENG_SYMBL.focus();
                    return false;
                }
                if (!$c.lc.fn_chkIsuSymblDoubleInput(edt_AFCHG_ISU_ENG_SYMBL.getValue(), txb_ISU_CD.getValue(), dts_Symbl)) {
                    await $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                    return false;
                }
            }
        }
    }

    /* 2009-04-24 종목명변경으로 중복입력체크 */
    ///*
    if (!$c.lc.fn_check_bz_doubleinput(dts_BZ_CHECK, txb_ISU_CD.getValue(), edt_MKTACT_ENFORCE_DD.getValue(), scwin.vBzProcsNo, LIST_BZ_TP_CD_140)) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name checkSave
 * @description (3264) 2010.12.27 ETF 종목명 변경
 * @returns {void}
 * @hidden N
 */
scwin.checkSave = function() {
    if (txb_AFCHG_ISU_KOR_NM.getValue() === "" || txb_AFCHG_ISU_KOR_NM.getValue() === "-") {
        dts_Isu.setCellData(1, "AFCHG_ISU_KOR_NM", txb_BFCHG_ISU_KOR_NM.getValue());
    }
    if (txb_AFCHG_ISU_KOR_ABBRV.getValue() === "" || txb_AFCHG_ISU_KOR_ABBRV.getValue() === "-") {
        dts_Isu.setCellData(1, "AFCHG_ISU_KOR_ABBRV", txb_BFCHG_ISU_KOR_ABBRV.getValue());
    }
    if (edt_AFCHG_ISU_ENG_NM.getValue() === "" || edt_AFCHG_ISU_ENG_NM.getValue() === "-") {
        dts_Isu.setCellData(1, "AFCHG_ISU_ENG_NM", txb_BFCHG_ISU_ENG_NM.getValue());
    }
    if (edt_AFCHG_ISU_ENG_ABBRV.getValue() === "" || edt_AFCHG_ISU_ENG_ABBRV.getValue() === "-") {
        dts_Isu.setCellData(1, "AFCHG_ISU_ENG_ABBRV", txb_BFCHG_ISU_ENG_ABBRV.getValue());
    }
    if (scwin.vSYMBL_INPUT_CD === '1') {
        if (edt_AFCHG_ISU_ENG_SYMBL.getValue() === "" || edt_AFCHG_ISU_ENG_SYMBL.getValue() === "-") {
            dts_Isu.setCellData(1, "AFCHG_ISU_ENG_SYMBL", txb_BFCHG_ISU_ENG_SYMBL.getValue());
        }
    }
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        if (scwin.vBzProcsNo === "") {
            scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        }
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);

            // (3264) 2010.12.27 ETF 종목명 변경
            if (scwin.vSecuGrpId === SECUGRP_ID_EF) {
                scwin.checkSave();
            }
            //-

            await scwin.trs(TRS_IDX_INSERT);
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;

        // (3264) 2010.12.27 ETF 종목명 변경
        if (scwin.vSecuGrpId === SECUGRP_ID_EF) {
            scwin.checkSave();
        }
        //-

        await scwin.trs(TRS_IDX_UPDATE);
    }
};

