        vCtnt += "\r\n";
        vCtnt += "3. 변경사유: 신탁계약 변경에 따른 종목명 변경";
        vCtnt += "\r\n";
        vCtnt += "4. 운용사(위탁사): " + dts_Isu.getCellData(1, "TRST_COM_NM");
        vCtnt += "\r\n";
    } else {
        vCtnt += "1. 변경내역(변경전 → 변경후)";
        vCtnt += "\r\n";
        vCtnt += "    - 한글종목명";
        vCtnt += "\r\n";
        vCtnt += "         o " + txb_BFCHG_ISU_KOR_NM.getValue() + " → " + txb_AFCHG_ISU_KOR_NM.getValue();
        vCtnt += "\r\n";
        vCtnt += "    - 영문종목명";
        vCtnt += "\r\n";
        vCtnt += "         o " + txb_BFCHG_ISU_ENG_NM.getValue() + " → " + edt_AFCHG_ISU_ENG_NM.getValue();
        vCtnt += "\r\n";
        vCtnt += "2. 변경일자: " + scwin.dateForm(edt_MKTACT_ENFORCE_DD.getValue());
