/**
 * @method
 * @name dateForm
 * @description date Form 처리
 * @param {String} pStr pStr
 * @returns {void}
 * @hidden N
 */
scwin.dateForm = function(pStr) {
    let str = "";
    if (pStr === "") {
        str = "★★★★년" + "★★월" + "★★일";
    } else {
        str = pStr.substring(0, 4) + "년" + pStr.substring(4, 6) + "월" + pStr.substring(6, 8) + "일";
    }
    return str;
};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    if (scwin.vBzProcsNo === '') {
        await $c.win.alert("공시안내문 생성 처리할 대상자료가 선택되지 않았거나, 없습니다.");
    }
    if ($c.cp.isModified(dts_Isu)) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68959"; // 68926:기타안내사항 -> 689599:종목명 변경) 으로 서식코드변경
        arr[1] = scwin.vBzProcsNo;
        arr[2] = scwin.vIsurCd;
        arr[3] = js_market;
        arr[4] = scwin.getIsuNmDisclsCtnt();
        if (scwin.vSecuGrpId === SECUGRP_ID_EF) {
            // 코스콤 전송시 접수에서 제목에 종목명을 셋팅해서 처리에서는 제외함.
            arr[5] = '';
        } else {
            arr[5] = txb_ISU_NM.getValue();
        }

        // CopyDataSet( dts_Isu , param_dts_isu) ;
        // CopyDataSet(dts_Isu , param_dts_mst);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_CD", txb_ISU_CD.getValue());
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 730 + 5;
    const hgt = 785 + 30;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

